//  SCRIPT 2 - DATOS DE AerolineaVIP_MongoBD (insertMany)
//  Autor : Jeremy Vilaña - Grupo 03 - Desarrollo Web (ASP.NET Core)
//
//  QUE HACE: inserta TODA la data real de la base SQL Server AerolineaVIP
//  en las 11 colecciones creadas por el Script 1. Vacia las colecciones
//  antes de insertar, asi se puede ejecutar varias veces.
//
//  COMO EJECUTARLO (primero el Script 1, luego este):
//    mongosh --file 01_Estructura_AerolineaVIP_Mongo.js
//    mongosh --file 02_Datos_AerolineaVIP_Mongo.js
//
//  NOTAS
//  - oid(col, n) arma un ObjectId fijo: "6a00" + codigo de coleccion + n en
//    hexadecimal. Asi cada relacion apunta siempre al mismo documento.
//    Codigos: 01 catalogos, 02 aeropuertos, 03 rutas, 04 aeronaves, 05 vuelos,
//    06 pasajeros, 07 itinerarios, 08 reservas, 09 asignaciones, 0a compras,
//    0b datosEmisor. n = Id original de SQL Server (idSql).
//  - Las fechas se guardan como ISODate con el mismo valor que en SQL Server.
//  - Los datos se generaron desde SQL Server (.\SQL2019, BD AerolineaVIP) el 16-nov-2026.
// ==========================================================================

use("AerolineaVIP_MongoBD");

const oid = (col, n) => ObjectId("6a00" + col + n.toString(16).padStart(18, "0"));

// Vacia las colecciones (los indices y validadores se conservan)
db.getCollectionNames().forEach(c => db.getCollection(c).deleteMany({}));

